  if (execution.rejectLimitDown && isOnePriceLimit(exitQuote, code, 'down')) return { ret: null, executable: false, reason: 'limit_down_unsellable' };
  const amount = typeof entryQuote === 'object' ? finiteNumber(entryQuote.amount) : null;
  if (Number(execution.minAmount || 0) > 0 && amount !== null && amount < Number(execution.minAmount)) return { ret: null, executable: false, reason: 'low_liquidity' };
  const commission = Math.max(Number(costs.minCommission || 0), entry * Number(costs.commissionRate || 0));
  const sellCommission = Math.max(Number(costs.minCommission || 0), exit * Number(costs.commissionRate || 0));
  const netEntry = entry * (1 + Number(costs.slippageRate || 0)) + commission;
  const netExit = exit * (1 - Number(costs.slippageRate || 0)) - sellCommission - exit * Number(costs.stampTaxRate || 0);
