  const band = (arr) => ({ p5: q(arr, 0.05), p50: q(arr, 0.5), p95: q(arr, 0.95) });
  return { n, samples: valid.length, tradingDays: dated ? rets.length : null, blockLength, sampling: dated ? 'whole-trading-day-block' : 'undated-observation', final: band(finals), maxDrawdown: band(draws), winRate: band(wins) };
